/**
 * Trips — local-first repository (tasks.md T066; Constitution II).
 *
 * A trip is written HERE first, with `is_dirty = true` and `synced_at = null`,
 * and read back through live queries. The sync engine (US6) pushes it later;
 * nothing in the UI calls `POST /trips`. The row's `id` is generated by the
 * caller with `expo-crypto`'s `randomUUID()` (research D-15) so the same
 * identity travels to the server unchanged.
 *
 * Rules every repository in this directory follows:
 *   - every write sets `updated_at = now` and `is_dirty = true`;
 *   - deletes are tombstones (`deleted_at`), never row removals (FR-039);
 *   - every read filters `deleted_at IS NULL` — the sync engine is the only
 *     reader that may see tombstones (sync-protocol.md §1).
 */
import { and, desc, eq, isNull } from 'drizzle-orm';

import type { AppDatabase } from '@/db/client';
import { tripStops, trips, type TripRow } from '@/db/schema';

import { nowIso } from './shared';

export interface CreateTripInput {
  /** Client-generated UUID (D-15). */
  id: string;
  title: string;
  /** ISO 4217, upper case — validated by the form with `CurrencyCode`. */
  home_currency: string;
}

/** Own trips, most recently changed first. Live-queryable. */
function listQuery(db: AppDatabase) {
  return db
    .select()
    .from(trips)
    .where(isNull(trips.deleted_at))
    .orderBy(desc(trips.updated_at));
}

/** One trip by id, or an empty result if it is gone. Live-queryable. */
function byIdQuery(db: AppDatabase, id: string) {
  return db
    .select()
    .from(trips)
    .where(and(eq(trips.id, id), isNull(trips.deleted_at)));
}

function create(db: AppDatabase, input: CreateTripInput): TripRow {
  const now = nowIso();
  const [row] = db
    .insert(trips)
    .values({
      id: input.id,
      title: input.title,
      home_currency: input.home_currency,
      is_public: false,
      cover_photo_id: null,
      status: 'planning',
      created_at: now,
      updated_at: now,
      deleted_at: null,
      is_dirty: true,
      synced_at: null,
    })
    .returning()
    .all();
  if (!row) throw new Error('Trip insert returned no row.');
  return row;
}

/**
 * Tombstone the trip and its live stops together, as the server does
 * (rest-api.md §3, DELETE /trips/:id). Both become dirty so the sync engine
 * propagates the whole removal, parents first.
 */
function remove(db: AppDatabase, id: string): void {
  const now = nowIso();
  db.transaction((tx) => {
    tx.update(trips)
      .set({ deleted_at: now, updated_at: now, is_dirty: true })
      .where(and(eq(trips.id, id), isNull(trips.deleted_at)))
      .run();
    tx.update(tripStops)
      .set({ deleted_at: now, updated_at: now, is_dirty: true })
      .where(and(eq(tripStops.trip_id, id), isNull(tripStops.deleted_at)))
      .run();
  });
}

export const tripsRepository = { listQuery, byIdQuery, create, remove };
